#include <cstdint>
#include <string>
#include <vector>

std::string displayText(const std::string& label)
{
    const auto at{ label.find("##") };
    return at == std::string::npos ? label : label.substr(0, at);
}

std::string idText(const std::string& label)
{
    const auto at{ label.find("###") };
    return at == std::string::npos ? label : label.substr(at);
}

uint32_t hashText(const std::string& text, uint32_t seed)
{
    uint32_t hash{ seed ^ 2166136261u };
    for (unsigned char b : text)
    {
        hash ^= b;
        hash *= 16777619u;
    }
    return hash;
}

class IdStack
{
public:
    explicit IdStack(uint32_t windowSeed) : m_seeds{ windowSeed } {}
    void push(const std::string& text) { m_seeds.push_back(hashText(text, m_seeds.back())); }
    void push(int n) { push(std::to_string(n)); }
    void pop() { if (m_seeds.size() > 1) m_seeds.pop_back(); }
    uint32_t idOf(const std::string& label) const { return hashText(idText(label), m_seeds.back()); }
private:
    std::vector<uint32_t> m_seeds;
};

unitTests:
TEST("display text") { CHECK_EQ(displayText("Delete"), std::string("Delete")); CHECK_EQ(displayText("Delete##3"), std::string("Delete")); CHECK_EQ(displayText("##speed"), std::string("")); CHECK_EQ(displayText("HP: 87###hp"), std::string("HP: 87")); }
TEST("id text") { CHECK_EQ(idText("Delete"), std::string("Delete")); CHECK_EQ(idText("Delete##3"), std::string("Delete##3")); CHECK_EQ(idText("##speed"), std::string("##speed")); CHECK_EQ(idText("HP: 87###hp"), std::string("###hp")); }
TEST("the hash") { CHECK_EQ(hashText("", 0), 2166136261u); CHECK_EQ(hashText("a", 0), 0xE40C292Cu); CHECK(hashText("a", 1) != hashText("a", 0)); }
TEST("same label, same id") { IdStack s{ 7 }; CHECK_EQ(s.idOf("Delete"), s.idOf("Delete")); }
TEST("## changes the id but not the display") { IdStack s{ 7 }; CHECK(s.idOf("Delete##1") != s.idOf("Delete##2")); }
TEST("### keeps the id stable") { IdStack s{ 7 }; CHECK_EQ(s.idOf("HP: 87###hp"), s.idOf("HP: 12###hp")); }
TEST("PushID separates loop items") {
    IdStack s{ 7 };
    s.push(0); const uint32_t first = s.idOf("Delete"); s.pop();
    s.push(1); const uint32_t second = s.idOf("Delete"); s.pop();
    CHECK(first != second); CHECK(first != s.idOf("Delete"));
}
TEST("push(int) is push of its text") { IdStack a{ 3 }, b{ 3 }; a.push(42); b.push("42"); CHECK_EQ(a.idOf("x"), b.idOf("x")); }
TEST("windows differ") { IdStack a{ hashText("Stones", 0) }, b{ hashText("Enemies", 0) }; CHECK(a.idOf("Delete") != b.idOf("Delete")); }
TEST("pop never removes the window seed") { IdStack s{ 9 }; const uint32_t before = s.idOf("x"); s.pop(); s.pop(); CHECK_EQ(s.idOf("x"), before); }

